using Karaoke.BUS;using Karaoke.DAL;using Karaoke.DTO;namespace Karaoke.GUI;public class MainForm:Form{readonly KaraokeService s=new();readonly FlowLayoutPanel roomGrid=new(){Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(15)};readonly DataGridView services=G(),billServices=G(),bills=G();int selectedRoom=0,selectedBill=0;static DataGridView G()=>new(){Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect};public MainForm(){Text="HỆ THỐNG QUẢN LÝ ĐẶT PHÒNG & DỊCH VỤ KARAOKE - BÀI 6.5";Width=1200;Height=750;var t=new TabControl{Dock=DockStyle.Fill};Controls.Add(t);var rp=new TabPage("Sơ đồ phòng hát");rp.Controls.Add(roomGrid);rp.Controls.Add(Top(B("Tải sơ đồ",LoadRooms),B("Mở phòng đang chọn",OpenRoom)));t.TabPages.Add(rp);var sp=new TabPage("Dịch vụ");var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Vertical};split.Panel1.Controls.Add(services);split.Panel2.Controls.Add(billServices);sp.Controls.Add(split);sp.Controls.Add(Top(B("Tải dịch vụ",()=>services.DataSource=s.Services()),B("Chọn hóa đơn đang hát",SelectBill),B("Gọi dịch vụ",AddService),B("Tải chi tiết",LoadBillServices)));t.TabPages.Add(sp);var bp=new TabPage("Hóa đơn & thanh toán");bp.Controls.Add(bills);bp.Controls.Add(Top(B("Tải hóa đơn đang mở",LoadBills),B("Thanh toán hóa đơn",Pay)));t.TabPages.Add(bp);Shown+=(_,_)=>Safe(()=>{using var c=Db.Open();LoadRooms();LoadBills();services.DataSource=s.Services();});}Control Top(params Control[] cs){var p=new FlowLayoutPanel{Dock=DockStyle.Top,Height=48};p.Controls.AddRange(cs);return p;}Button B(string n,Action a){var b=new Button{Text=n,AutoSize=true,Height=32};b.Click+=(_,_)=>Safe(a);return b;}void LoadRooms(){roomGrid.Controls.Clear();var t=s.Rooms();foreach(System.Data.DataRow r in t.Rows){int id=Convert.ToInt32(r["MaPhong"]);string status=Convert.ToString(r["TrangThai"])??"Trống";var b=new Button{Width=190,Height=100,Text=$"{r["TenPhong"]}\n{status}\n{Convert.ToDecimal(r["GiaTheoGio"]):N0} đ/giờ",BackColor=status=="Trống"?Color.LightGreen:Color.LightCoral,Tag=id};b.Click+=(_,_)=>{selectedRoom=id;Text=$"KARAOKE - Đang chọn phòng {id}";};roomGrid.Controls.Add(b);}}void OpenRoom(){if(selectedRoom==0)throw new Exception("Hãy chọn phòng trên sơ đồ.");selectedBill=s.OpenRoom(selectedRoom);LoadRooms();LoadBills();MessageBox.Show("Đã mở phòng. Mã hóa đơn: "+selectedBill);}void LoadBills(){bills.DataSource=s.ActiveBills();}void SelectBill(){if(bills.CurrentRow!=null)selectedBill=Convert.ToInt32(bills.CurrentRow.Cells["MaHD"].Value);else if(selectedBill==0)throw new Exception("Chọn hóa đơn đang mở ở tab Hóa đơn.");LoadBillServices();}void LoadBillServices(){if(selectedBill==0)throw new Exception("Chưa chọn hóa đơn.");billServices.DataSource=s.BillServices(selectedBill);}void AddService(){if(selectedBill==0)SelectBill();if(services.CurrentRow==null)throw new Exception("Chọn dịch vụ.");int id=Convert.ToInt32(services.CurrentRow.Cells["MaDV"].Value);int q=int.Parse(Prompt("Số lượng:","1"));s.AddServices(selectedBill,new(){new ServiceItem{MaDV=id,SoLuong=q}});LoadBillServices();}void Pay(){if(bills.CurrentRow==null)throw new Exception("Chọn hóa đơn cần thanh toán.");int id=Convert.ToInt32(bills.CurrentRow.Cells["MaHD"].Value);s.Pay(id);LoadBills();LoadRooms();MessageBox.Show("Thanh toán thành công, phòng đã được trả.");}static string Prompt(string l,string v){using var f=new Form{Text=l,Width=350,Height=140,StartPosition=FormStartPosition.CenterParent};var t=new TextBox{Left=10,Top=15,Width=310,Text=v};var b=new Button{Text="OK",Left=245,Top=52,DialogResult=DialogResult.OK};f.Controls.AddRange(new Control[]{t,b});f.AcceptButton=b;return f.ShowDialog()==DialogResult.OK?t.Text:v;}void Safe(Action a){try{a();}catch(Exception e){MessageBox.Show(e.Message,"Thông báo",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}}